__d(function(a,o,e,s,r,i,d){r.exports={titulo:"Pol\xedtica de Privacidade",versao:"2026-11-22",secoes:[{titulo:"Em resumo",paragrafos:["O app funciona sem conta e n\xe3o pede nome, e-mail nem telefone. Quem se inscreve para testar o beta informa nome e e-mail em uma p\xe1gina \xe0 parte.","Seus Salvos e os Lugares marcados como J\xe1 fui ficam s\xf3 no seu celular. Sua localiza\xe7\xe3o nunca \xe9 gravada por n\xf3s.","Coletamos dados de uso, ligados a um c\xf3digo aleat\xf3rio, para entender o que melhorar. Voc\xea pode desligar isso na aba Voc\xea."]},{titulo:"No site",paragrafos:["O Simb\xf3 tamb\xe9m funciona no navegador, em simbo.app.br, sem conta. O site registra dados de uso como o app, ligados a um c\xf3digo aleat\xf3rio, e voc\xea pode desligar em \"Enviar dados de uso\", na aba Voc\xea. Quando uma tela falha, ele envia ao PostHog um aviso curto com o tipo do erro e a tela, sem links, e-mails ou n\xfameros que identifiquem algu\xe9m.","Salvos, J\xe1 fui e suas prefer\xeancias ficam s\xf3 no navegador que voc\xea usa. Somem se voc\xea limpar os dados do site ou tocar em \"Apagar meus dados deste aparelho\", na aba Voc\xea.","O hist\xf3rico da aba Voc\xea (o que voc\xea abriu, salvou, sorteou, mandou para os amigos e de onde pediu a rota) e os rol\xeas que voc\xea marca (dia, quantas pessoas v\xe3o e quanto quer gastar) ficam s\xf3 neste aparelho ou navegador. N\xe3o s\xe3o enviados para os nossos servidores. Voc\xea apaga o hist\xf3rico em \"Apagar tudo\", na pr\xf3pria aba Voc\xea, e cada rol\xea no bot\xe3o de desmarcar. O progresso de um roteiro que voc\xea est\xe1 seguindo (em que paradas voc\xea marcou \"Cheguei\") fica neste aparelho e, se voc\xea entrou na sua conta, tamb\xe9m na conta, para voc\xea continuar em outro aparelho. S\xf3 voc\xea v\xea. Ele some quando voc\xea para de seguir o roteiro.","Quando voc\xea manda o convite de um rol\xea marcado, guardamos nos nossos servidores o Lugar, o dia, quantas pessoas v\xe3o e o primeiro nome que voc\xea usou para convidar. Quem recebe o link responde sem criar conta, informando s\xf3 o primeiro nome e a resposta (topo, talvez ou n\xe3o d\xe1). Os nomes de quem respondeu s\xf3 aparecem para quem convidou, no aparelho dele. O convite e as respostas s\xe3o apagados 7 dias depois do dia do rol\xea.","Para abrir mais r\xe1pido, o site guarda no navegador uma c\xf3pia da lista de Lugares e dos pr\xf3prios arquivos. Essa c\xf3pia n\xe3o tem dados seus, e nada \xe9 enviado por causa dela.","A localiza\xe7\xe3o s\xf3 \xe9 usada se voc\xea permitir no navegador e n\xe3o \xe9 enviada para os nossos servidores. O mapa do site vem do OpenFreeMap, com dados do OpenStreetMap, que recebe dados t\xe9cnicos da conex\xe3o, como o endere\xe7o de internet e a \xe1rea do mapa que voc\xea est\xe1 vendo."]},{titulo:"Quem \xe9 respons\xe1vel",paragrafos:["O Simb\xf3, que antes se chamava Rol\xea SP, \xe9 um projeto de Ant\xf4nio, que decide como esses dados s\xe3o usados e responde por eles."]},{titulo:"O que fica s\xf3 no seu celular",paragrafos:["Salvos, J\xe1 fui e suas prefer\xeancias no app. Tudo isso some quando voc\xea desinstala o app, limpa os dados dele ou toca em \"Apagar meus dados deste aparelho\", na aba Voc\xea."]},{titulo:"Localiza\xe7\xe3o",paragrafos:["O app s\xf3 usa a localiza\xe7\xe3o se voc\xea permitir, e enquanto estiver aberto. Ela serve para abrir o mapa perto de voc\xea e mostrar o que est\xe1 por perto.","N\xe3o enviamos sua localiza\xe7\xe3o para os nossos servidores nem para as ferramentas de an\xe1lise. O app funciona igual sem ela, e voc\xea pode retirar a permiss\xe3o nos ajustes do Android."]},{titulo:"Inscri\xe7\xe3o no beta",paragrafos:["Na p\xe1gina de inscri\xe7\xe3o, pedimos seu nome e seu e-mail, com a data do aceite. Usamos s\xf3 para saber quem participa do teste e enviar pesquisas sobre ele, com base no seu consentimento.","Esses dados ficam no Supabase, s\xf3 a equipe respons\xe1vel tem acesso, e eles n\xe3o s\xe3o usados para publicidade nem compartilhados. Apagamos at\xe9 12 meses depois do fim do beta, ou antes, se voc\xea pedir."]},{titulo:"Notas dos Lugares",paragrafos:["Se voc\xea der nota a um Lugar, guardamos a nota com um c\xf3digo aleat\xf3rio deste aparelho, sem nome nem conta, para evitar notas repetidas. A m\xe9dia \xe9 p\xfablica, e ningu\xe9m v\xea quem deu cada nota.","Para apagar suas notas, toque em \"Apagar meus dados deste aparelho\", na aba Voc\xea."]},{titulo:"Coment\xe1rios",paragrafos:["Se voc\xea comentar um Lugar, ficam p\xfablicos o texto, o que voc\xea disse que pediu, quanto gastou por pessoa e se achou o pre\xe7o justo, junto com a nota que voc\xea deu e a data, sem seu nome. Guardamos o coment\xe1rio com um c\xf3digo aleat\xf3rio deste aparelho, para que s\xf3 voc\xea possa editar ou tirar, e nunca mostramos esse c\xf3digo.","N\xe3o escreva dados pessoais, seus ou de outras pessoas. Se voc\xea denunciar um coment\xe1rio, guardamos a den\xfancia com o mesmo c\xf3digo, para contar uma vez s\xf3.","Para apagar tudo, toque em \"Apagar meus dados deste aparelho\", na aba Voc\xea. Sem o aparelho, escreva para antonio@simbo.app.br informando o Lugar e o texto."]},{titulo:"Sugest\xf5es de lugares",paragrafos:["Se voc\xea sugerir um lugar, guardamos o que escreveu com um c\xf3digo aleat\xf3rio deste aparelho, sem nome nem conta, s\xf3 para limitar envios autom\xe1ticos. N\xe3o escreva dados pessoais na descri\xe7\xe3o. Ao tocar em \"Apagar meus dados deste aparelho\", a sugest\xe3o perde a liga\xe7\xe3o com o aparelho."]},{titulo:"Respostas sobre as informa\xe7\xf5es",paragrafos:["Se voc\xea responder se as informa\xe7\xf5es de um Lugar est\xe3o certas, guardamos a resposta com um c\xf3digo aleat\xf3rio deste aparelho, sem nome nem conta, para avisar a equipe do que precisa ser corrigido. A resposta n\xe3o \xe9 p\xfablica.","Para apagar suas respostas, toque em \"Apagar meus dados deste aparelho\", na aba Voc\xea."]},{titulo:"Dados de uso",paragrafos:["Registramos o que acontece no app: telas e Lugares abertos, filtros usados, textos digitados na busca, sorteios, Lugares salvos e compartilhados. Em \"Sinto falta\", voc\xea pode deixar um e-mail: ele serve s\xf3 para avisar o andamento daquele pedido e sai quando voc\xea apaga seus dados. Em \"Quero ser parceiro\", o nome e o contato que voc\xea deixa servem s\xf3 para responder o pedido; para apagar, escreva para a gente. Na web, registramos tamb\xe9m de onde voc\xea chegou, como um link compartilhado ou outro site. Junto v\xe3o um c\xf3digo aleat\xf3rio do app, o modelo do celular e a vers\xe3o do sistema.","Evite digitar dados pessoais na busca. Usamos essas informa\xe7\xf5es para melhorar o app, com base no nosso leg\xedtimo interesse. Elas ficam guardadas por at\xe9 12 meses.","Para desligar o envio, use a op\xe7\xe3o \"Enviar dados de uso\" na aba Voc\xea."]},{titulo:"Relat\xf3rios de erro",paragrafos:["Quando o app falha, podemos receber um relat\xf3rio t\xe9cnico com o erro, o modelo do celular e a vers\xe3o do sistema, para corrigir o problema."]},{titulo:"Com quem os dados passam",paragrafos:["PostHog recebe os dados de uso e Sentry recebe os relat\xf3rios de erro. Essas empresas podem guardar dados fora do Brasil, inclusive nos Estados Unidos.","Supabase entrega a lista de Lugares e Mapbox entrega o mapa. Para isso, recebem dados t\xe9cnicos da conex\xe3o, como o endere\xe7o de internet e a \xe1rea do mapa que voc\xea est\xe1 vendo.","N\xe3o vendemos seus dados."]},{titulo:"Publicidade",paragrafos:["O Simb\xf3 \xe9 gratuito e pode exibir publicidade, como banners, destaques e sugest\xf5es de parceiros. Toda publicidade \xe9 identificada e n\xe3o muda a posi\xe7\xe3o nem a avalia\xe7\xe3o dos Lugares.","Anunciantes podem receber n\xfameros somados, como quantas pessoas viram ou salvaram um Lugar. N\xe3o entregamos a eles dados que identifiquem voc\xea."]},{titulo:"Fotos dos Lugares",paragrafos:["Algumas fotos v\xeam de p\xe1ginas p\xfablicas, com a origem indicada nos cr\xe9ditos. Se uma foto \xe9 sua e voc\xea quer que ela saia, escreva para antonio@simbo.app.br com o link, e n\xf3s a retiramos."]},{titulo:"Quando voc\xea sai do app",paragrafos:["Abrir uma rota, o Instagram de um Lugar ou compartilhar pelo WhatsApp leva voc\xea a outros servi\xe7os, que t\xeam suas pr\xf3prias regras."]},{titulo:"Crian\xe7as e adolescentes",paragrafos:["O app n\xe3o \xe9 voltado a crian\xe7as e inclui bares e casas noturnas."]},{titulo:"Seus direitos",paragrafos:["Pela Lei Geral de Prote\xe7\xe3o de Dados, voc\xea pode pedir para saber quais dados temos, corrigi-los ou apag\xe1-los, al\xe9m de se opor ao uso deles.","Para isso, escreva para antonio@simbo.app.br. Como n\xe3o temos seu nome, informe o c\xf3digo que aparece na aba Voc\xea, em \"Seu c\xf3digo no app\"."]},{titulo:"Mudan\xe7as",paragrafos:["Se esta pol\xedtica mudar, a vers\xe3o nova aparece aqui com a data atualizada. Ela mudar\xe1 antes de o app ter conta ou ir para a loja."]}]}},988,[]);